CREATE TRIGGER RefCusMap_Version_Create
	ON RefCusMap
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT ZZM_PK, 'ZZM'
	FROM inserted
GO
CREATE TRIGGER RefCusMap_Version_Update
	ON RefCusMap
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ZZM_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
