	INSERT @sourcePK
	SELECT ZZM_PK, 'ZZM' FROM inserted
	UNION
	SELECT ZZM_PK, 'ZZM' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
